#include <bits/stdc++.h>
using namespace std;

#define LOOP(i, start, end) for(int i=start; i<=end; ++i)
#define REVERSE(i, start, end) for(int i=start; i>=end; --i)

typedef long long ll;

inline int getInt() {
    int x=0, sign=1; char c;
    while((c=getchar()) && (c<'0' || c>'9') && c!='-');
    if(c=='-') { sign=-1; c=getchar(); }
    do { x=(x*10)+(c^'0'); } while((c=getchar())>='0' && c<='9');
    return x*sign;
}

inline ll getLong() {
    ll x=0; int sign=1; char c;
    while((c=getchar()) && (c<'0' || c>'9') && c!='-');
    if(c=='-') { sign=-1; c=getchar(); }
    do { x=(x*10)+(c^'0'); } while((c=getchar())>='0' && c<='9');
    return x*sign;
}

const int MAXN=32, MOD=1000000007;

void addTo(int &a, int b) {
    a+=b; if(a>=MOD) a-=MOD;
}

struct Matrix {
    int mat[MAXN][MAXN];
    void zero() { memset(mat,0,sizeof(mat)); }
    void printMatrix() {
        LOOP(i,1,n+1) {
            LOOP(j,1,n+1) printf("%d%c", mat[i][j], j==n?'\n':' ');
        }
        putchar('\n');
    }
    Matrix operator*(const Matrix &rhs) const {
        Matrix res; res.zero();
        LOOP(i,1,n+1) LOOP(j,1,n+1) LOOP(k,1,n+1)
            addTo(res.mat[i][j], (ll)mat[i][k]*rhs.mat[k][j]%MOD);
        return res;
    }
};

int n;
Matrix identity, A[MAXN], prefix[MAXN], suffix[MAXN], answer;

int main() {
#ifndef ONLINE_JUDGE
    freopen("matrix.in","r",stdin);
    freopen("matrix.out","w",stdout);
#endif
    ll m= getLong(); n= getInt();
    identity.zero();
    LOOP(i,1,n) identity.mat[i][i]=1;
    answer=identity;
    LOOP(i,1,n) {
        A[i]=identity;
        A[i].mat[i][i]=1;
    }
    prefix[0]=identity; suffix[n+1]=identity;

    for(;m; m/=n) {
        ll u=m%n;
        if(u) {
            ll s=0, v=m/n;
            while(v) { s=(s+v%n)%n; v/=n; }
            u=(s+u-1)%n+1;
            for(; u!=s; --u) {
                if(u<=0) u+=n;
                answer=A[u]*answer;
            }
        }
        LOOP(i,1,n) prefix[i]=prefix[i-1]*A[i];
        for(int i=n; i>=1; --i) suffix[i]=A[i]*suffix[i+1];
        LOOP(i,1,n) A[i]=suffix[i]*prefix[i-1];
    }
    int res=1;
    LOOP(i,1,n) addTo(res, answer.mat[n+1][i]);
    printf("%d\n", res);
    return 0;
}
